package com.example.prjmetrix

import androidx.room3.ColumnInfo
import androidx.room3.Entity
import androidx.room3.PrimaryKey

// Room entity: each HabitEntity object represents one row in the habits table.
// It stores a local copy so habits can still be viewed and updated offline (Gaur, 2025).
@Entity(tableName = "habits")
data class HabitEntity(

    // Local ID is generated by Room, while serverId identifies the habit in the API.
    // serverId stays null until an offline habit has been uploaded.
    @PrimaryKey(autoGenerate = true) val localId: Int = 0,
    @ColumnInfo(name = "server_id") val serverId: Int? = null,

    val label: String,
    @ColumnInfo(name = "icon_key") val iconKey: String = "check",
    @ColumnInfo(name = "color_hex") val colorHex: String = "#29B6F6",
    @ColumnInfo(name = "gold_coins") val goldCoins: Int = 5,
    val progress: Float = 0f,

    // Stores the date for the progress so it can reset for a new day.
    @ColumnInfo(name = "progress_date") val progressDate: String,

    // True means the change still needs to be sent to the API during sync.
    @ColumnInfo(name = "pending_sync") val pendingSync: Boolean = false
)

